import React from "react";
import { Link } from "react-router-dom";
import '../App.css';

function Dashboard() {
  return (
    <div className="seller-dashboard-container">
      <h2>Seller Dashboard</h2>
      <p>Manage your listings below:</p>
      <ul style={{ listStyle: "none", padding: 0 }}>
        <li style={{ marginBottom: "10px" }}>
          <Link to="/add-listing" style={linkStyle}>Add New Listing</Link>
        </li>
        <li style={{ marginBottom: "10px" }}>
          <Link to="/view-listings" style={linkStyle}>View Listings</Link>
        </li>
        <li style={{ marginBottom: "10px" }}>
          <Link to="/edit-listing/1" style={linkStyle}>Edit Listing</Link> {/* Example ID */}
        </li>
      </ul>
    </div>
  );
}

const linkStyle = {
  color: "#4A90E2",
  textDecoration: "none",
  fontWeight: "bold",
  fontSize: "16px",
};

export default Dashboard;
